const path = require('path');
const fs = require('fs');
let lastBuildCall = null;
module.exports = {
    build: async (opts) => {
        lastBuildCall = opts;
        const platform = Object.keys(opts).find((k) => ['win', 'mac', 'linux'].includes(k));
        const isDir = Array.isArray(opts[platform]) && opts[platform].includes('dir');
        const rootDir = process.cwd();
        if (isDir) {
            // 与真实 electron-builder 对齐：创建 appOutDir，但 artifacts 返回空数组
            // 真实命名规则见 src/electron/build-targets.js#computeUnpackedDir
            const arch = Object.keys(opts).find((k) => ['ia32', 'x64', 'armv7l', 'arm64', 'universal', 'loong64'].includes(k)) || 'x64';
            const dirName = platform === 'mac'
                ? (arch === 'x64' ? 'mac' : `mac-${arch}`)
                : `${platform}${arch === 'x64' ? '' : `-${arch}`}-unpacked`;
            const unpackedDir = path.join(rootDir, 'dist', dirName);
            fs.mkdirSync(unpackedDir, { recursive: true });
            fs.writeFileSync(path.join(unpackedDir, 'placeholder.txt'), 'unpacked');
            return [];
        }
        return [path.join(rootDir, 'dist', 'fake-installer.exe')];
    },
    _getLastCall: () => lastBuildCall,
    _clearLastCall: () => { lastBuildCall = null; },
};
